int main(void){p66_bias_io io,old;agc_word channel11,oldchannel;enum dsky_nv_mission mission;uint16_t failures=0;uint8_t n,g;for(n=0;n<128u;++n)failures=(uint16_t)(failures+dsky_nv_blank_checkpoint(n,&s,&before));for(n=0;n<8u;++n)for(g=0;g<14u;++g){if(!dsky_nv_blank_checkpoint_input((uint8_t)(n*16u),&s,&io,&channel11,&mission))return 2;switch(g){case 0:s.words[5]=0;break;case 1:s.words[4]=060000;break;case 2:s.words[3]=1;break;case 3:s.words[6]^=1;break;case 4:s.words[7]=1;break;case 5:io.superbank=1;break;case 6:io.interrupt_enabled=2;break;case 7:channel11=0100000;break;case 8:s.words[0123]=AGC_NEG_ZERO;break;case 9:s.words[0]=040000;break;case 10:s.words[01016]=0100000;break;case 11:s.words[01023]=0100000;break;case 12:io.superbank=060;break;default:mission=(enum dsky_nv_mission)2;break;}before=s;old=io;oldchannel=channel11;if(dsky_nv_blank(&s,&io,&channel11,mission)!=P66_BIAS_OUT_OF_SCOPE||memcmp(&s,&before,sizeof s)||memcmp(&io,&old,sizeof io)||channel11!=oldchannel)++failures;}printf("128 full LM/CM BLANKDSP source states and112 unchanged invalid guards: %s\n",failures?"FAIL":"PASS");return failures?1:0;}
